import sys
import time
fn bump(value: ref i64, left: ref i64, right: ref i64) {
  value = value + 4
  left = left + 5
  right = right + 6
  Coro.yield()
  value = value + 1
  left = left + 2
  right = right + 3
  const stamp = time.now()
  value = value + stamp - stamp
}
fn answer() -> i64 {
  var value = 10
  var live = sys.Pipe(2147483642, 2147483643)
  defer { live.closeRead(); live.closeWrite() }
  const snapshot = live._readHandle
  bump(ref value, ref live._readHandle, ref live._writeHandle)
  return value + live.readEnd() + live.writeEnd() + snapshot
}

interface Reader { read() -> i64 }
class One implements Reader {
  read() -> i64 { return 42 }
}
fn delayed(reader: Reader) -> i64 {
  Coro.yield()
  return reader.read()
}
fn answer() -> i64 {
  var reader: Reader = One()
  const result = delayed(reader)
  return result + reader.read() - 42
}

